


export type CreateWebhookEndpointRequest = { /** Set default to follow the merchant default, or a supported YYYY-MM-DD version to pin this endpoint. Omission follows the merchant default. Null is not accepted. */ "api_version"?: string; "description"?: string; "enabled"?: boolean; /** Event types this endpoint receives. Empty means all merchant-owned events. For partner_app sources, empty defaults to all app lifecycle events. For installed_merchants sources, provide at least one installed-merchant event. */ "enabled_events"?: Array<string>; /** Event sources this endpoint receives. Defaults to merchant. Use partner_app for app lifecycle events and installed_merchants for events from merchants that installed the partner app. */ "event_sources"?: Array<"merchant" | "partner_app" | "installed_merchants" | (string & {})>; /** Partner-source delivery mode. Valid values are test, live, and both. Mode applies to installed_merchants events; partner_app lifecycle events require both. */ "mode"?: "test" | "live" | "both" | (string & {}); /** Partner app that owns partner_app or installed_merchants event sources. */ "partner_app_id"?: string; "url": string; };
